import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem107 preserva identidade, links e preço',()=>{for(const [n,titulo,expected,link] of [["5952869866","Escova Dental Oralgos Db781 Cs 4000 Cerdas Cores Variadas","Escova dental Oralgos DB781 CS — pacote anunciado com 6 unidades","https://www.mercadolivre.com.br/up/MLBU3580523497?wid=MLB5952869866"],["6118982036","Kit De Sobrevivência De Emergência De Acampamento Aventura","Kit De Sobrevivência De Emergência De Acampamento Aventura","https://www.mercadolivre.com.br/up/MLBU3700781669?wid=MLB6118982036"],["6203660830","Kit 4 Shorts 2 Em 1 Duplo Dryfit Masculino Compressão Térmic","Kit com 4 shorts masculinos 2 em 1","https://produto.mercadolivre.com.br/MLB-6203660830-kit-4-shorts-2-em-1-duplo-dryfit-masculino-compresso-termic-_JM?searchVariation=196379598601"]]){const p={id:'mlMLB'+n,titulo,link,comentario:'anterior',preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);for(const k of ['id','preco','linkAfiliado','link'])assert.equal(x[k],p[k]);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,link:'https://produto.mercadolivre.com.br/MLB-123'}).comentario,p.comentario);}});
